B=[
('الْمُقَوْقِسُ','Mukavkıs',[
('كَانَتْ مِصْرُ تَحْتَ حُكْمِ الرُّومِ، وَكَانَ حَاكِمُهَا الْمُقَوْقِسُ يَسْكُنُ فِي حِصْنِ بَابِلْيُونَ.','Mısır Rum yönetimi altındaydı; yöneticisi Mukavkıs Babylon kalesinde oturuyordu.'),
('وَكَانَ الْقِبْطُ أَهْلُ مِصْرَ يَكْرَهُونَ الرُّومَ، لِأَنَّهُمْ كَانُوا يَضْطَهِدُونَهُمْ فِي دِينِهِمْ.','Mısır halkı Kıptîler Rumlardan nefret ediyordu; çünkü onlara dinleri yüzünden zulmediyorlardı.'),
('وَكَانَ لِلْمُقَوْقِسِ بِنْتٌ ذَكِيَّةٌ اسْمُهَا أَرْمَانُوسَةُ.','Mukavkıs’ın Armanûsa adında zeki bir kızı vardı.'),
('وَقَدْ خَطَبَهَا قُسْطَنْطِينُ ابْنُ مَلِكِ الرُّومِ، وَلَكِنَّ قَلْبَهَا لَمْ يَمِلْ إِلَيْهِ.','Rum kralının oğlu Konstantin onu istemişti ama kalbi ona meyletmedi.'),
('فَأَرْسَلَهَا أَبُوهَا فِي مَوْكِبٍ إِلَى بِلْبِيسَ، فِي طَرِيقِهَا إِلَى زَوْجِهَا.','Babası onu kocasına giden yolda bir alayla Bilbeys’e gönderdi.')]),
('عَمْرُو بْنُ الْعَاصِ','Amr b. Âs',[
('وَفِي سَنَةِ ثَمَانِي عَشْرَةَ لِلْهِجْرَةِ دَخَلَ عَمْرُو بْنُ الْعَاصِ مِصْرَ بِجَيْشٍ صَغِيرٍ.','Hicrî 18 yılında Amr b. Âs küçük bir orduyla Mısır’a girdi.'),
('فَحَاصَرَ بِلْبِيسَ وَفَتَحَهَا، وَكَانَتْ أَرْمَانُوسَةُ فِيهَا.','Bilbeys’i kuşattı ve fethetti; Armanûsa oradaydı.'),
('فَجَاءَ بِهَا الْجُنُودُ إِلَى عَمْرٍو، وَهِيَ خَائِفَةٌ.','Askerler onu korkmuş hâlde Amr’a getirdiler.'),
('فَقَالَ عَمْرٌو: «لَا تَخَافِي؛ إِنَّنَا لَا نُؤْذِي النِّسَاءَ.»','Amr dedi ki: “Korkma; biz kadınlara eziyet etmeyiz.”'),
('ثُمَّ أَرْسَلَهَا إِلَى أَبِيهَا مُكَرَّمَةً، وَمَعَهَا كُلُّ مَالِهَا وَخَدَمِهَا.','Sonra onu bütün malı ve hizmetçileriyle birlikte saygıyla babasına gönderdi.'),
('فَتَعَجَّبَ الْمُقَوْقِسُ مِنْ هَذَا الْكَرَمِ، وَقَالَ: «هَؤُلَاءِ قَوْمٌ لَيْسُوا كَغَيْرِهِمْ.»','Mukavkıs bu cömertliğe şaştı ve dedi ki: “Bunlar başkalarına benzemeyen bir kavim.”')]),
('الْحِصْنُ','Kale',[
('ثُمَّ حَاصَرَ عَمْرٌو حِصْنَ بَابِلْيُونَ سَبْعَةَ أَشْهُرٍ.','Sonra Amr Babylon kalesini yedi ay kuşattı.'),
('وَأَرْسَلَ الْمُقَوْقِسُ رُسُلًا إِلَى الْمُسْلِمِينَ لِيَعْرِفَ أَحْوَالَهُمْ.','Mukavkıs Müslümanların hâlini öğrenmek için onlara elçiler gönderdi.'),
('فَرَجَعَ الرُّسُلُ وَقَالُوا: «رَأَيْنَا قَوْمًا الْمَوْتُ أَحَبُّ إِلَيْهِمْ مِنَ الْحَيَاةِ.»','Elçiler dönüp dediler ki: “Ölümün kendilerine hayattan daha sevimli olduğu bir kavim gördük.”'),
('«لَا يُعْرَفُ أَمِيرُهُمْ مِنْ عَبْدِهِمْ، وَيَغْسِلُونَ أَطْرَافَهُمْ وَيُصَلُّونَ فِي خُشُوعٍ.»','“Emirleri kölelerinden ayırt edilmez; uzuvlarını yıkar ve huşu içinde namaz kılarlar.”'),
('فَمَالَ الْمُقَوْقِسُ إِلَى الصُّلْحِ، وَلَكِنَّ الرُّومَ رَفَضُوا.','Mukavkıs barışa meyletti ama Rumlar reddetti.'),
('ثُمَّ صَعِدَ الزُّبَيْرُ بْنُ الْعَوَّامِ سُورَ الْحِصْنِ بِسُلَّمٍ، وَكَبَّرَ، فَفُتِحَ الْحِصْنُ.','Sonra Zübeyr b. Avvâm bir merdivenle kalenin suruna tırmandı ve tekbir getirdi; kale fethedildi.')]),
('الْإِسْكَنْدَرِيَّةُ','İskenderiye',[
('ثُمَّ سَارَ عَمْرٌو إِلَى الْإِسْكَنْدَرِيَّةِ، أَعْظَمِ مُدُنِ الرُّومِ فِي مِصْرَ.','Sonra Amr Rumların Mısır’daki en büyük şehri İskenderiye’ye yürüdü.'),
('فَحَاصَرَهَا، ثُمَّ صَالَحَ أَهْلَهَا عَلَى الْجِزْيَةِ، وَخَرَجَ الرُّومُ مِنْهَا بِالْبَحْرِ.','Onu kuşattı, sonra halkıyla cizye üzerine barış yaptı; Rumlar oradan denizden çıktılar.'),
('وَتُرِكَ لِلْقِبْطِ كَنَائِسُهُمْ وَدِينُهُمْ، وَرَجَعَ بَطْرِيرْكُهُمْ الَّذِي هَرَبَ مِنَ الرُّومِ سِنِينَ.','Kıptîlere kiliseleri ve dinleri bırakıldı; Rumlardan yıllarca kaçan patrikleri geri döndü.'),
('وَبَنَى عَمْرٌو مَدِينَةَ الْفُسْطَاطِ، وَفِيهَا مَسْجِدُهُ الَّذِي مَا زَالَ قَائِمًا.','Amr Fustât şehrini kurdu; hâlâ ayakta olan mescidi oradadır.'),
('وَتَذَكَّرَتْ أَرْمَانُوسَةُ يَوْمَ رَجَعَتْ إِلَى أَبِيهَا سَالِمَةً، فَقَالَتْ: «الْعَدْلُ يَفْتَحُ الْقُلُوبَ قَبْلَ الْأَبْوَابِ.»','Armanûsa babasına sağ salim döndüğü günü hatırladı ve dedi ki: “Adalet kapılardan önce kalpleri açar.”')]),
]
